class Solution:
    def largestSumAfterKNegations(self, A: List[int], K: int) -> int:
        # Create a min-heap from the array
        heapq.heapify(A)

        # Flip the smallest element K times
        for _ in range(K):
            smallest = heapq.heappop(A)
            heapq.heappush(A, -smallest)

